def head(title,desc,slug='',schemas=None,noindex=False):
 url=BASE+slug
 social='gaming-guide-preview-v2.png' if slug=='gaming-buying-guide.html' else 'gardezi-finds-social.png'
 data=''.join('<script type="application/ld+json">'+json.dumps(x,ensure_ascii=False).replace('<','\\u003c')+'</script>' for x in schemas or [])
 return f'''<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><link rel="canonical" href="{url}"><meta name="theme-color" content="#172439"><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="stylesheet" href="assets/site.css?v={VERSION}"><meta property="og:type" content="website"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{url}"><meta property="og:site_name" content="Gardezi Finds"><meta property="og:locale" content="en_US"><meta property="og:image" content="{BASE}assets/{social}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="{E(title)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:site" content="@gardezi84"><meta name="twitter:title" content="{E(title)}"><meta name="twitter:description" content="{E(desc)}"><meta name="twitter:image" content="{BASE}assets/{social}"><link rel="sitemap" type="application/xml" href="sitemap.xml">{data}<script async src="https://www.googletagmanager.com/gtag/js?id=G-DJH5D9HG7X"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments)}}gtag('js',new Date());gtag('config','G-DJH5D9HG7X');</script><script defer src="assets/site.js?v={VERSION}"></script></head><body>'''
def crumbs(name,slug,parent=None):
 items=[('Home','')]+([parent] if parent else [])+[(name,slug)]
 return {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':BASE+p} for i,(n,p) in enumerate(items)]}
def breadcrumb(name):return f'<nav class="breadcrumb" aria-label="Breadcrumb"><a href="./">Home</a><span aria-hidden="true">/</span><span>{E(name)}</span></nav>'
def fallback(sym,hidden=False):return f'<div class="product-placeholder"{ " hidden" if hidden else ""}>{icon(sym)}<small>See product details on Amazon</small></div>'
def card(p,i=0,sym='spark'):
 image=p.get('image');rating=p.get('rating');title=p['title'];url=p['url']
 media=f'<img src="{E(image)}" alt="{E(title)}" width="240" height="200" loading="lazy" decoding="async" referrerpolicy="no-referrer">'+fallback(sym,True) if image else fallback(sym)
 rated=f'★ {float(rating):.1f} <span>· supplied rating</span>' if rating else '<span>Check reviews on Amazon</span>'
 return f'''<article class="product-card" data-title="{E(title)}" data-search="{E((title+' '+p.get('category','')+' '+p['asin']).lower())}" data-rating="{rating or 0}" data-photo="{1 if image else 0}" data-order="{i}"><div class="product-media">{media}</div><div class="product-tag">{E(p.get('brand') or p.get('category'))}</div><h3><a href="{E(url)}" target="_blank" rel="sponsored nofollow noopener" data-affiliate data-asin="{p['asin']}" data-title="{E(title)}">{E(title)}</a></h3><div class="product-rating">{rated}</div><div class="product-asin">ASIN: {p['asin']}</div><a class="buy" href="{E(url)}" target="_blank" rel="sponsored nofollow noopener" data-affiliate data-asin="{p['asin']}" data-title="{E(title)}" aria-label="View {E(title)} on Amazon">View on Amazon <span aria-hidden="true">↗</span></a></article>'''

def product_note():return '<p class="results-note">Supplied ratings come from the source catalog, with no observation date. They are not live ratings or our own reviews. Check Amazon for current details.</p>'
def tips(g):return '<aside class="shopping-tips" aria-label="Shopping checklist"><h2>Before you choose</h2><div class="tip-list">'+''.join(f'<p><strong>{E(h)}</strong>{E(t)}</p>' for h,t in g[6])+'</div></aside>'
def tools():return '<div class="collection-tools"><label class="field search-field" for="filter"><span>Search</span><input id="filter" type="search" placeholder="Filter this collection by product name or ASIN"></label><label class="field" for="sort"><span>Sort</span><select id="sort"><option value="photos">Photos first</option><option value="az">Name: A–Z</option><option value="rating">Supplied rating</option></select></label></div>'
def categories_nav(g):return '<nav class="category-nav" aria-label="Product collections">'+''.join(f'<a href="{a[0]}.html"{ " aria-current=\"page\"" if a[0]==g[0] else ""}>{E(a[1])}</a>' for a in GROUPS)+'</nav>'

def build_collection(g):
 slug,name,cats,sym,tint,desc,_=g;items=collection(g)
 schema={'@context':'https://schema.org','@type':'CollectionPage','name':name,'description':desc,'url':BASE+slug+'.html','isPartOf':{'@type':'WebSite','name':'Gardezi Finds','url':BASE},'mainEntity':{'@type':'ItemList','numberOfItems':len(items),'itemListElement':[{'@type':'ListItem','position':i+1,'name':p['title'],'url':p['url']} for i,p in enumerate(items)]}}
 title={'electronics-tech':'Tech & Charging Accessories','home-kitchen':'Home & Kitchen Finds','beauty-care':'Beauty & Personal Care','video-games':'Nintendo, PlayStation, Xbox & PC Games','gaming-accessories':'Controllers & Gaming Accessories','automotive-tools':'Car Accessories & Automotive Tools'}.get(slug,name)+' | Gardezi Finds'
 intro=f'<div class="collection-head"><div class="icon-box" style="--tint:{tint}">{icon(sym)}</div><div><h1>{E(name)}</h1><p>{E(desc)}</p></div></div>'
 cards=''.join(card(p,i,sym) for i,p in enumerate(items))
 empty=f'<div id="empty" class="empty"{ " hidden" if items else ""}><h2>No matching products yet</h2><p>{"Try another search or browse a different collection." if items else "This collection is ready for future additions. Explore our toys and games for more gift ideas."}</p><a class="text-link" href="toys-games.html">Explore toys & games →</a></div>'
 guide={'toys-games':'kids-toys','pets':'pet-accessories','electronics-tech':'tech-accessories','video-games':'gaming','gaming-accessories':'gaming','roblox':'gaming','jewelry':'jewelry','beauty-care':'beauty-care'}.get(slug)
 related=(f'<p><a class="text-link" href="{guide}-buying-guide.html">Read the related shopping guide →</a></p>' if guide else '')
 out=head(title,desc,slug+'.html',[schema,crumbs(name,slug+'.html')],noindex=not bool(items))+header()+f'<main class="wrap" id="main">{breadcrumb(name)}{intro}{categories_nav(g)}{tips(g)}{tools()}<p id="result-count" class="count" role="status" aria-live="polite">{len(items)} products in this collection</p><div class="products" data-product-grid>{cards}</div>{empty}{product_note()}{related}</main>'+footer()+'</body></html>'
 (ROOT/(slug+'.html')).write_text(out)
 return len(items)

def home():
 tiles=''.join(f'<a class="category-tile" href="{g[0]}.html"><div class="icon-box" style="--tint:{g[4]}">{icon(g[3])}</div><strong>{E(g[1])}</strong><small>{len(collection(g))} finds <span aria-hidden="true">→</span></small></a>' for g in GROUPS if collection(g))
 chosen=[]
 # A diverse, image-led selection, rather than filling the homepage with one category.
 for g in GROUPS[:15]:
  item=next((p for p in collection(g) if p.get('image') and not re.search('protection plan|toner|ink cartridge',p['title'],re.I)),None)
  if item and item['asin'] not in {p['asin'] for p in chosen}:chosen.append(item)
 featured=''.join(card(p,i) for i,p in enumerate(chosen[:12]))
 hero=[]
 for asin,label,path in [('B0DMD26R83','A little power. A lot of possibility.','electronics-tech'),('B0BLJ1LPV5','Make room for more play.','toys-games')]:
  p=next(x for x in PRODUCTS if x['asin']==asin)
  hero.append(f'<a class="hero-tile" href="{path}.html"><img src="{E(p["image"])}" alt="{E(p["title"])}" width="220" height="210" fetchpriority="high"><small>{"Everyday tech" if path=="electronics-tech" else "Playtime discoveries"}</small><strong>{label}</strong></a>')
 desc='Discover Amazon finds for home, beauty, tech, jewelry and gaming. Explore useful collections and practical shopping guides for US shoppers.'
 schema={'@context':'https://schema.org','@type':'WebSite','@id':BASE+'#website','name':'Gardezi Finds','url':BASE,'description':desc,'inLanguage':'en-US','publisher':{'@type':'Organization','name':'Gardezi Finds','url':BASE,'sameAs':['https://x.com/gardezi84','https://www.threads.com/@gadgetguyfinds']}}
 out=head('Amazon Finds for Home, Tech, Beauty & Games | Gardezi Finds',desc,schemas=[schema])+header()+f'''<main id="main" class="wrap"><section class="hero"><div><p class="eyebrow">Everyday discoveries. Thoughtfully organized.</p><h1>Little finds.<br><em>Everyday upgrades.</em></h1><p>Discover useful Amazon finds for your home, your routine and your next favorite hobby. Less searching. More finding.</p><div class="hero-actions"><a class="button" href="#collections">Explore collections <span aria-hidden="true">→</span></a><a class="text-link" href="#guides">Shop a little smarter</a></div></div><div class="hero-art">{''.join(hero)}<p class="hero-badge">Tech, play and the things in between.</p></div></section><div class="value-strip"><span><b>{len(PRODUCTS):,} products</b> to explore</span><span><b>{sum(bool(collection(g)) for g in GROUPS)} collections</b> for your everyday</span><span><b>Amazon.com</b> · built for US shoppers</span></div><section class="section" id="collections"><div class="section-head"><div><p class="eyebrow">Find your corner</p><h2>What are you shopping for?</h2><p>Explore a collection, then discover the details that matter.</p></div><a class="text-link" href="category.html?all=1">Search all finds →</a></div><div class="category-grid">{tiles}</div></section><div class="deal-grid"><section class="deal-card"><div><p class="eyebrow">Explore on Amazon</p><h2>Give your cart a fresh start.</h2><p>Browse Amazon’s available coupon offers. Eligibility and discounts vary.</p></div><a class="button light" href="https://amzn.to/4hxthjB" data-affiliate data-deal="coupon" rel="sponsored nofollow noopener" target="_blank">Browse coupons ↗</a></section><section class="deal-card"><div><p class="eyebrow">Something worth a look</p><h2>Explore today’s deal offers.</h2><p>Check current offers, prices and availability directly on Amazon.</p></div><a class="button" href="https://amzn.to/3Vr0BjO" data-affiliate data-deal="daily_deals" rel="sponsored nofollow noopener" target="_blank">Daily deals ↗</a></section></div><section class="section"><div class="section-head"><div><p class="eyebrow">A few places to start</p><h2>Everyday finds, across your favorites.</h2><p>Explore a mix of products from our collections.</p></div></div><div class="products">{featured}</div>{product_note()}</section><section class="section" id="guides"><div class="section-head"><div><p class="eyebrow">A little guidance goes a long way</p><h2>Know what to look for.</h2><p>Simple checks to help you choose with confidence.</p></div></div><div class="guides-grid">{guide_tiles()}</div></section></main>'''+footer()+'</body></html>'
