def enrich_guide(slug, content):
 picks = GUIDE_PICKS.get(slug)
 if not picks: return content
 content = re.sub(r'<!-- guide-picks:start -->.*?<!-- guide-picks:end -->', '', content, flags=re.S)
 cards = []
 for source, asin, name, purpose, check in picks:
  html = (ROOT/source).read_text()
  match = next((m for m in re.findall(r'<article class="product-card".*?</article>', html, re.S) if f'data-asin="{asin}"' in m), None)
  if not match: raise ValueError(f'Missing guide product: {asin}')
  match = match.replace('<article class="product-card"', '<div class="product-card"', 1).replace('</article>', '</div>')
  match = re.sub(r'(<h3><a[^>]*>).*?(</a></h3>)', lambda m: m[1]+E(name)+m[2], match, count=1, flags=re.S)
  match = re.sub(r'<div class="product-rating">.*?</div>', '', match, flags=re.S)
  match = re.sub(r'<div class="product-asin">.*?</div>', '', match, flags=re.S)
  note = f'<p><strong>{E(purpose)}</strong><br>Check before buying: {E(check)}</p>'
  match = match.replace('<a class="buy"', note+'<a class="buy"', 1)
  cards.append(match)
 links = ('<a class="button" data-guide-link href="video-games.html">Browse all video games →</a> <a class="text-link" data-guide-link href="gaming-accessories.html">Gaming accessories →</a>' if slug=='gaming-buying-guide' else '<a class="button" data-guide-link href="pets.html">Browse all pet finds →</a>')
 if slug=='jewelry-buying-guide': links='<a class="button" data-guide-link href="jewelry.html">Browse all jewelry →</a>'
 if slug=='beauty-care-buying-guide': links='<a class="button" data-guide-link href="beauty-care.html">Browse all beauty finds →</a>'
 block = '<!-- guide-picks:start --><section aria-labelledby="guide-picks-heading"><h2 id="guide-picks-heading">Three options to explore</h2><p>Examples from our catalog, selected for different uses. Compare the details below; these are not hands-on reviews or a ranking.</p><div class="products">'+''.join(cards)+'</div><p>'+links+'</p><p class="results-note">Check the selected variant, current price, availability and delivery on Amazon.</p></section><!-- guide-picks:end -->'
 intro = re.search(r'<p class="intro">.*?</p>', content, re.S)
 if not intro: raise ValueError('Guide has no introduction')
 return content[:intro.end()]+block+content[intro.end():]

EDITORIAL_UPDATED = "2026-10-10"
GUIDE_DETAILS = {'jewelry-buying-guide': '<section aria-labelledby="comparison-heading"><h2 id="comparison-heading">Compare jewelry by what matters</h2><div class="table-wrap"><table><thead><tr><th scope="col">Type</th><th scope="col">Measure</th><th scope="col">Read on the listing</th></tr></thead><tbody><tr><td>Earrings</td><td>Diameter, drop length and weight</td><td>Post material, plating and closure</td></tr><tr><td>Bracelet</td><td>Wrist fit and adjustable range</td><td>Base metal, clasp and care instructions</td></tr><tr><td>Necklace</td><td>Chain length and pendant dimensions</td><td>Finish, extender and package contents</td></tr></tbody></table></div><h2>Common buying questions</h2><h3>Does 14K gold-plated mean solid 14K gold?</h3><p>No. Gold plating is a surface layer over another material. Check the base metal and finish description separately; do not treat a plated listing as a solid-gold listing.</p><h3>Which jewelry measurements should I check for a gift?</h3><p>Check chain length for necklaces, wrist fit for bracelets, and diameter or drop length for earrings. Compare those dimensions with a piece the recipient already wears.</p><h2>Source for material terminology</h2><p>The <a href="https://consumer.ftc.gov/articles/buying-platinum-gold-and-silver-jewelry" rel="noopener" target="_blank">FTC guide to buying platinum, gold and silver jewelry</a> explains material and plating terminology. Use it for general shopping guidance; use each selected Amazon listing for current product details.</p></section>', 'beauty-care-buying-guide': '<section aria-labelledby="comparison-heading"><h2 id="comparison-heading">Compare beauty products by their role</h2><div class="table-wrap"><table><thead><tr><th scope="col">Product role</th><th scope="col">Compare</th><th scope="col">Confirm before ordering</th></tr></thead><tbody><tr><td>Cleansing balm</td><td>Formula, texture and container size</td><td>Selected variant and directions</td></tr><tr><td>Moisturizer</td><td>Ingredient list, fragrance and texture</td><td>Pack size and intended use</td></tr><tr><td>Lip balm</td><td>Tint, scent and tube size</td><td>Exact shade and package contents</td></tr></tbody></table></div><h2>Common buying questions</h2><h3>How do I compare different pack sizes?</h3><p>Divide the product price by the total quantity in the pack, using the same unit for both products. Include delivery charges and distinguish a one-time offer from a subscription.</p><h3>Where should I check the ingredient list?</h3><p>Read the label on the current product package and compare it with the manufacturer or current listing for the exact variant. A product name alone does not identify its full formula.</p><h2>Source for understanding cosmetic labels</h2><p>The <a href="https://www.fda.gov/cosmetics/cosmetics-labeling/cosmetic-ingredient-names" rel="noopener" target="_blank">FDA explanation of cosmetic ingredient names</a> provides background on ingredient labeling. It does not endorse the selected products. Use each Amazon listing and the current package for product-specific details.</p></section>'}

def guide_editorial(slug, content):
 content = re.sub(r'<!-- editorial:start -->.*?<!-- editorial:end -->', '', content, flags=re.S)
 content = re.sub(r'<p class="meta">.*?</p>', '', content, flags=re.S)
 meta = '<!-- editorial:start --><p class="meta">Published by <a href="about.html">Gardezi Finds</a> · Updated <time datetime="'+EDITORIAL_UPDATED+'">October 10, 2026</time></p><!-- editorial:end -->'
 heading = re.search(r'</h1>', content)
 if heading: content=content[:heading.end()]+meta+content[heading.end():]
 content = re.sub(r'<!-- guide-details:start -->.*?<!-- guide-details:end -->', '', content, flags=re.S)
 if slug in GUIDE_DETAILS: content+='<!-- guide-details:start -->'+GUIDE_DETAILS[slug]+'<!-- guide-details:end -->'
 return content

def article_page(slug,title,desc,content):
 content = guide_editorial(slug, enrich_guide(slug, content))
 schema={'@context':'https://schema.org','@type':'Article','dateModified':EDITORIAL_UPDATED,'headline':title,'description':desc,'url':BASE+slug+'.html','author':{'@type':'Organization','name':'Gardezi Finds','url':BASE+'about.html'},'publisher':{'@type':'Organization','name':'Gardezi Finds','url':BASE},'inLanguage':'en-US','mainEntityOfPage':BASE+slug+'.html'}
 (ROOT/(slug+'.html')).write_text(head(title+' | Gardezi Finds',desc,slug+'.html',[schema,crumbs(title,slug+'.html')])+header()+f'<main id="main" class="wrap">{breadcrumb("Shopping guide")}<article class="article">{content}</article></main>'+footer()+'</body></html>')

def kids_toys_guide():
 article_page('kids-toys-buying-guide', 'Kids’ Toy Shopping Guide for US Families', 'Compare kids’ toys by age guidance, play style, space and budget. A practical US gift checklist for building sets, plush toys, games and creative kits.', '<p class="eyebrow">Kids’ toys &amp; gifts · US shopping guide</p>\n<h1>Kids’ toy shopping guide: choose for age, interests and everyday play.</h1>\n<p class="intro">A good toy gift fits the child and the home it is going to. Use this guide to compare building sets, plush toys, board games and creative kits before shopping for a birthday, holiday or everyday surprise.</p>\n<div class="notice">This is a shopping checklist, not a hands-on product test or safety certification. Check the current manufacturer information and Amazon listing before buying. As an Amazon Associate, Gardezi Finds earns from qualifying purchases.</div>\n<h2>Start with the age label and warnings</h2>\n<p>Read the manufacturer’s age guidance and every warning for the exact version you plan to buy. Do not treat an age label as simply a measure of difficulty. Small parts can pose a choking hazard to children under 3; a toy intended for an older sibling may need separate storage. The <a href="https://www.cpsc.gov/FAQ/Small-Parts-and-Choking-Hazard-Labeling-FAQs">US Consumer Product Safety Commission explains small-parts warnings</a> and the risks they address.</p>\n<p>If the listing does not show clear age guidance, instructions or a recognizable manufacturer, look for that information before ordering. Search the exact brand and model in the <a href="https://www.cpsc.gov/Recalls">CPSC recalls and product safety warnings database</a>, including when considering a secondhand toy.</p>\n<h2>Choose a play style the child already enjoys</h2>\n<p>Ask what the child returns to: making things, telling stories, solving puzzles or playing with other people. Then use the comparison below to narrow the format. Each individual toy still needs to match its manufacturer’s age guidance.</p>\n<div style="overflow-x:auto"><table><caption>Toy types and details to compare before buying</caption><thead><tr><th scope="col">Toy type</th><th scope="col">Why consider it?</th><th scope="col">Check first</th></tr></thead><tbody>\n<tr><th scope="row">Building sets</th><td>For children who enjoy assembling, rebuilding or displaying a project.</td><td>Piece sizes, instructions, finished dimensions and compatibility with sets already owned.</td></tr>\n<tr><th scope="row">Plush toys</th><td>For a favorite animal, character or make-believe companion.</td><td>Actual height, care instructions, attached accessories and age label.</td></tr>\n<tr><th scope="row">Board and card games</th><td>For shared family time or play with friends.</td><td>Minimum players, typical session length, reading requirements and small pieces.</td></tr>\n<tr><th scope="row">Pretend-play sets</th><td>For acting out stories, roles and everyday activities.</td><td>Included accessories, assembly, play-space footprint and storage.</td></tr>\n<tr><th scope="row">Creative kits</th><td>For a child who enjoys making a finished project.</td><td>Adult-help requirements, tools, cleanup and whether supplies are refillable.</td></tr>\n<tr><th scope="row">Puzzles</th><td>For matching, sorting and working toward a completed picture.</td><td>Piece dimensions, picture complexity, finished size and a surface to work on.</td></tr>\n</tbody></table></div>\n<h2>Match the toy to the household</h2>\n<p>Measure where a large set will be used and stored. Compare the assembled dimensions with the box dimensions; they describe different things. For smaller homes or travel, consider a compact set with a container that closes securely.</p>\n<p>Read the setup instructions before promising an immediate play session. Decide who can help with assembly, whether sound has a volume control, and how pieces will be put away. For a game, make sure the household can regularly provide the required number of players.</p>\n<h2>Set a total budget in US dollars</h2>\n<p>Compare the checkout total, including shipping and tax, plus any required batteries, accessories or refills. A lower shelf price can mean fewer included items. A larger set is worthwhile only if the extra pieces suit the child’s interests and your available space.</p>\n<p>For two similar kits, list what each includes and what you would need to buy separately. Check whether a pictured accessory is part of the selected package. Prices, stock and delivery estimates can change, so use the current listing rather than an old screenshot or catalog price.</p>\n<h2>Before you order a gift</h2>\n<ul><li>Ask a parent or caregiver about interests, age guidance and toys already owned.</li><li>Confirm the exact size, color, edition and item count selected.</li><li>Check the seller and delivery estimate for the recipient’s US ZIP code.</li><li>Review return conditions, gift-receipt options and packaging.</li><li>Leave time for adult assembly or setup when the instructions require it.</li></ul>\n<h2>Common toy-shopping questions</h2>\n<h3>Should I choose by age or interests?</h3><p>Use both: first check the manufacturer’s age guidance and warnings, then choose among suitable options based on what the child enjoys. Interest in a toy does not override its warnings.</p>\n<h3>Are the highest-rated toys always the best gift?</h3><p>A rating cannot tell you whether the toy fits your child, storage space or household routine. Read reviews for the same variant and look for concrete details about assembly, missing pieces and everyday use. Reviews do not establish safety compliance.</p>\n<h3>What if I do not know what they already have?</h3><p>Ask the caregiver for a short wishlist or a photo of the collection. Confirm compatibility before buying an expansion, and check that an expansion does not require a separate base game.</p>\n<div class="cta"><h2>Compare toys for your next gift</h2><p>Browse the collection, then open the current listing to check age guidance, package contents and delivery.</p><a class="button" data-guide-link href="toys-games.html">Browse toys &amp; games →</a></div>\n<p>Shopping for a console player? Read our <a href="gaming-buying-guide.html">gaming gift buying guide</a> for platform, edition and format checks.</p>')

def guides():
 kids_toys_guide()
 article_page('jewelry-buying-guide','How to choose jewelry and jewelry gifts','Compare jewelry materials, plating, dimensions, closures and gift details before choosing earrings, bracelets or necklaces on Amazon.','<p class="eyebrow">Jewelry &amp; gifts · shopping guide</p><h1>Choose jewelry for the person, the fit and the occasion.</h1><p class="intro">Start with the style they already wear: small hoops, a pendant or a bracelet stack. Then compare the material and dimensions so the gift is a useful match, not just an attractive photograph.</p><h2>Read the material description carefully</h2><p>Gold-plated, gold-filled and solid gold describe different constructions. A gold-plated item has a surface layer of gold over another material. Check the base metal as well as the finish, and read the seller’s material description for posts, chains and clasps separately.</p><h2>Compare dimensions with something you own</h2><p>For earrings, check hoop diameter, drop length and item weight. For necklaces, compare chain length and any extender with the neckline you plan to wear. For bracelets, measure your wrist and check the adjustable range or interior dimensions rather than relying on a size label.</p><h2>Choose the closure and finish for everyday use</h2><p>Check whether earrings use posts, hinges or hooks, and whether bracelets have a clasp or a stretch band. Read the care instructions before assuming a plated piece is suitable for showering or swimming. Marketing descriptions such as “waterproof” or “hypoallergenic” do not replace the material details.</p><h2>Make the gift easy to get right</h2><p>Confirm the selected color, item count, packaging and return conditions. A set may contain several pairs while a different variant contains one. Check the estimated delivery date for the recipient’s ZIP code and whether gift packaging is included.</p><div class="cta"><h2>Find a style to compare</h2><p>Explore earrings, bracelets and necklaces, then check the current listing for material and sizing details.</p><a class="button" data-guide-link href="jewelry.html">Browse jewelry →</a></div>')
 article_page('beauty-care-buying-guide','How to choose beauty and personal care products','Compare beauty product ingredients, texture, fragrance, package size and routine fit before choosing cleansers, moisturizers or lip care on Amazon.','<p class="eyebrow">Beauty &amp; personal care · shopping guide</p><h1>Build a beauty routine around what you actually use.</h1><p class="intro">Choose a product for a clear role in your routine: cleansing, moisturizing or lip care. Compare the formula, texture and package size before adding another bottle to your shelf.</p><h2>Start with the product’s intended use</h2><p>Read where and how the product is intended to be used. A cleanser, face moisturizer and lip balm serve different purposes. Check the directions and selected variant rather than choosing by a brand name or front-label claim alone.</p><h2>Read the full ingredient and fragrance details</h2><p>Use the ingredient list on the current listing or package to compare formulas with products you already use. Check fragrance information and any ingredients you already avoid. Variants of the same product may have different formulas, scents or tints.</p><h2>Compare texture and packaging</h2><p>Decide whether you prefer a balm, gel, lotion or cream. Check whether it comes in a tube, pump or jar and how it fits your travel or bathroom setup. For tinted lip products, compare the chosen shade with the finish shown in the listing.</p><h2>Compare cost per unit, not just the bottle price</h2><p>Confirm the size in ounces or grams and the number of items in the pack. Divide the total product price by the total quantity when comparing equivalent sizes. Include delivery charges and check whether the offer is a one-time purchase or a subscription.</p><h2>Check the current offer</h2><p>Review the selected variant, seller, delivery estimate and return conditions. Read recent reviews for details about texture, scent, packaging and the same variant you intend to buy. Catalog ratings are not a substitute for these checks.</p><h2>Beauty shopping checklist for US buyers</h2><p>Start with one product you want to replace or one gap in your routine. Write down the texture, finish, fragrance preference and package size you actually use. This makes it easier to compare similar products without buying a set simply because it contains more items.</p><h3>Makeup: compare the exact shade and finish</h3><p>Check the selected shade name and number, coverage description and finish. A listing may combine several shades or sizes, so confirm your selection again in the cart. Use manufacturer swatches as a starting point; screen colors and lighting can change how a shade appears. Check the seller’s return conditions before opening the package.</p><h3>Hair care: check the formula and format</h3><p>Distinguish shampoo, conditioner, rinse-out treatments and leave-in products. Read the intended use and directions for the exact formula. Compare bottle size, pump or cap design, and whether a pictured pair is sold as a set or as separate items.</p><h3>Beauty tools: plan for cleaning and replacements</h3><p>For brushes and applicators, check dimensions, materials, cleaning directions and included pieces. For powered tools, confirm US power compatibility, the plug or charging connection, included accessories and replacement-part availability. A travel adapter alone does not establish voltage compatibility; use the manufacturer’s specifications.</p><h2>Build a beauty gift around the recipient</h2><p>Ask about favorite shades, scents and products before choosing a gift. Check whether a gift set contains full-size products, minis or samples, and compare the total quantity with buying the items separately. Avoid assuming that a familiar brand means every formula or fragrance will suit the recipient.</p><ul><li>Confirm the seller, selected variant and sealed-package condition described in the listing.</li><li>Compare the total in US dollars, including shipping and tax, and check for recurring subscription terms.</li><li>Use the recipient’s ZIP code for the delivery estimate and check gift-receipt options.</li><li>Read return conditions for beauty products before purchasing, especially for opened items.</li></ul><h3>Is a luxury product automatically a better buy?</h3><p>A higher price alone does not establish that a product will suit your preferences. Compare the formula information, quantity, packaging and purpose. If trying a new product, compare a smaller size with the full-size option before committing to a larger purchase.</p><div class="cta"><h2>Explore your next everyday essential</h2><p>Browse beauty and personal care finds, then compare the current formula and pack details on Amazon.</p><a class="button" data-guide-link href="beauty-care.html">Browse beauty &amp; personal care →</a></div>')
 article_page('tech-accessories-buying-guide','How to choose charging & tech accessories','Compare device compatibility, charging specifications, connection types and package contents before buying tech accessories on Amazon.', '''<p class="eyebrow">Everyday tech · shopping guide</p><h1>Find the right accessories for the devices you own.</h1><p class="intro">A charging block, cable or computer accessory can look right and still be a poor fit. Start with your device’s requirements, then compare the details on the current listing.</p><div class="notice">This is a buying checklist, not a hands-on product review. We have not independently tested every product in our catalog.</div><h2>1. Start with the exact device</h2><p>Write down the device model and the connection you need. Check the manufacturer’s compatibility information, especially for adapters, replacement parts and accessories intended for a particular model.</p><h2>2. Read the power and connection details</h2><p>Compare the accessory’s specifications with your device’s documented requirements. A matching connector alone does not establish charging speed, display support or data-transfer capability. Check the charger, cable and device requirements together.</p><h2>3. Check everything in the package</h2><p>Look for the included item count, cable length, adapters and batteries. A listing for a charger may not include a cable. A pictured device may be shown for illustration and sold separately.</p><h2>4. Choose for the place you will use it</h2><p>For a desk, check available space and cable reach. For travel, check size and plug type. For a replacement accessory, compare the model and manufacturer instructions before ordering.</p><h2>5. Review the actual offer</h2><p>Confirm the selected variant, seller, current price, delivery and return terms on Amazon. Catalog ratings on this website are supplied averages without an observation date, so read the current reviews on the destination listing.</p><div class="cta"><h2>Explore your everyday tech options</h2><p>Browse charging accessories, computer gear and other electronics in one collection.</p><a class="button" href="electronics-tech.html">Browse electronics & tech →</a></div>''')
 article_page('gaming-buying-guide','How to choose video games & gaming gifts','Choose a gaming gift by checking the platform, edition, physical or digital format, regional details and required accessories.', '''<p class="eyebrow">Games & gifts · shopping guide</p><h1>A great gaming gift starts with the right platform.</h1><p class="intro">Before choosing a title, find out what the recipient plays on. Then check the exact edition and format. These small details matter more than an attractive cover or a familiar game name.</p><div class="notice">Listings in our collection may include multiple platforms and regional editions. Always confirm the selected variant on Amazon.</div><h2>1. Match the platform and model</h2><p>Ask whether the recipient uses Nintendo Switch, PlayStation, Xbox or a PC. Match the selected listing to the exact device and check any compatibility information supplied by the manufacturer.</p><h2>2. Choose physical or digital</h2><p>Read the listing to see whether it includes a physical game, a digital code, an expansion or other content. Check whether the recipient’s device can use that format. Do not assume that every edition includes the full base game.</p><h2>3. Read the regional and edition details</h2><p>Review the listing’s language, regional designation and edition contents. For digital content, confirm that the intended account and region are supported. For an imported physical edition, review the manufacturer’s guidance on game and downloadable-content compatibility.</p><h2>4. Check age guidance and access requirements</h2><p>Look at the age rating and content description. Read whether the game requires an account, internet connection, subscription, another game or additional accessories. Confirm these requirements with the recipient before giving the gift.</p><h2>5. Accessories need their own compatibility check</h2><p>For a controller or headset, match the exact console or computer. Check wired and wireless connections, included batteries and cables, and whether an adapter is required.</p><div class="cta"><h2>Explore the gaming collections</h2><p>Browse game listings and accessory options separately so you can focus on what you need.</p><a class="button" href="video-games.html">Browse video games →</a> <a href="gaming-accessories.html">Explore gaming accessories</a></div>''')

