 p=ROOT/'pet-accessories-buying-guide.html';old=p.read_text();content=re.search(r'<article[^>]*>(.*?)</article>',old,re.S).group(1) if '<article' in old else re.search(r'<main[^>]*>(.*?)</main>',old,re.S).group(1)
 content=re.sub(r'<p class="crumb">.*?</p>','',content,flags=re.S)
